local SealEngraver = {}
local PRODUCTS = {
    wax_seal = { name = "Voščeni pečat", waxCost = 1, time = 1, cost = 5, securityLevel = 10, description = "Preprost voščeni pečat." },
    signet_ring = { name = "Pečatnik", metalCost = 2, jewelCost = 1, time = 5, cost = 100, securityLevel = 30, prestige = 5, description = "Prstan z grbom." },
    official_seal = { name = "Uradni pečat", metalCost = 3, time = 7, cost = 200, securityLevel = 50, prestige = 8, description = "Državni pečat." },
    royal_seal = { name = "Kraljevski pečat", goldCost = 3, jewelCost = 2, time = 14, cost = 500, securityLevel = 80, prestige = 20, description = "Veliki kraljevski pečat." },
    seal_matrix = { name = "Pečatnik matrica", metalCost = 4, time = 10, cost = 250, securityLevel = 60, description = "Kovinska matrica za pečate." },
    counterseal = { name = "Protipečat", metalCost = 2, waxCost = 1, time = 5, cost = 80, securityLevel = 40, description = "Dodatni pečat za varnost." },
}
local BUILDINGS = {
    workshop = { name = "Pečatarska delavnica", cost = { gold = 300, wood = 100, iron = 30 }, upkeep = 8, qualityBonus = 5 },
    engraving_studio = { name = "Graverski atelje", cost = { gold = 1000, wood = 200, stone = 200, iron = 50 }, upkeep = 25, qualityBonus = 20 },
    seal_vault = { name = "Pečatni trezor", cost = { gold = 2000, wood = 300, stone = 500, iron = 100 }, upkeep = 40, qualityBonus = 25, securityBonus = 20 },
    royal_engraver = { name = "Kraljevski graver", cost = { gold = 5000, wood = 400, stone = 800, iron = 200 }, upkeep = 100, qualityBonus = 40, prestigeBonus = 20 },
}
SealEngraver.waxStock = 10; SealEngraver.metalStock = 8; SealEngraver.goldStock = 3; SealEngraver.jewelStock = 2
SealEngraver.productStock = {}; SealEngraver.buildings = {}; SealEngraver.engraver = nil; SealEngraver.activeMaking = {}; SealEngraver.totalProducts = 0; SealEngraver.dayTimer = 0
function SealEngraver.init() SealEngraver.waxStock=10; SealEngraver.metalStock=8; SealEngraver.goldStock=3; SealEngraver.jewelStock=2; SealEngraver.productStock={}; SealEngraver.buildings={}; SealEngraver.engraver=nil; SealEngraver.activeMaking={}; SealEngraver.totalProducts=0; SealEngraver.dayTimer=0; print("[SealEngraver] Royal Seal Engraver & Signet Maker System initialized (6 products, 4 buildings)") end
function SealEngraver.hireEngraver(n,s) s=s or math.random(40,85); local c=400+s*8; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; SealEngraver.engraver={name=n or ("Graver "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Graver najet: %s (spretnost: %d)",SealEngraver.engraver.name,s),"success") end; return true end
function SealEngraver.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function SealEngraver.build(id) local ok,e=SealEngraver.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(SealEngraver.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function SealEngraver.getQualityBonus() local b=0; for _,bd in ipairs(SealEngraver.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function SealEngraver.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.waxCost and SealEngraver.waxStock<(d.waxCost or 0) then return false,"Premalo voska" end; if d.metalCost and SealEngraver.metalStock<(d.metalCost or 0) then return false,"Premalo kovine" end; if d.goldCost and SealEngraver.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and SealEngraver.jewelStock<(d.jewelCost or 0) then return false,"Premalo dragih kamnov" end; if #SealEngraver.buildings==0 then return false,"Potrebna delavnica" end; if not SealEngraver.engraver then return false,"Potreben graver" end; return true end
function SealEngraver.make(pt) local ok,e=SealEngraver.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.waxCost then SealEngraver.waxStock=SealEngraver.waxStock-d.waxCost end; if d.metalCost then SealEngraver.metalStock=SealEngraver.metalStock-d.metalCost end; if d.goldCost then SealEngraver.goldStock=SealEngraver.goldStock-d.goldCost end; if d.jewelCost then SealEngraver.jewelStock=SealEngraver.jewelStock-d.jewelCost end; local t=d.time; if SealEngraver.engraver then t=math.max(1,t-math.floor(SealEngraver.engraver.skill/12)) end; table.insert(SealEngraver.activeMaking,{id="seal_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost,securityLevel=d.securityLevel or 0,prestige=d.prestige or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Graviranje: %s (%d dni)",d.name,t),"info") end; return true end
function SealEngraver.completeMaking(m) local q=1.0+(SealEngraver.getQualityBonus()/100); if SealEngraver.engraver then q=q+(SealEngraver.engraver.skill/200) end; q=math.min(2.0,q); SealEngraver.productStock[m.productType]=(SealEngraver.productStock[m.productType] or 0)+1; SealEngraver.totalProducts=SealEngraver.totalProducts+1; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if SealEngraver.engraver then SealEngraver.engraver.itemsMade=SealEngraver.engraver.itemsMade+1; if math.random()<0.15 then SealEngraver.engraver.skill=math.min(100,SealEngraver.engraver.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pečat izdelan: %s (kakovost: %.1f)",m.productName,q),"success") end end
function SealEngraver.update(dt) if not _G.state then return end; SealEngraver.dayTimer=SealEngraver.dayTimer+dt; if SealEngraver.dayTimer>=30 then SealEngraver.dayTimer=0; for i=#SealEngraver.activeMaking,1,-1 do local m=SealEngraver.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then SealEngraver.completeMaking(m); table.remove(SealEngraver.activeMaking,i) end end; local tu=0; for _,bd in ipairs(SealEngraver.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if SealEngraver.engraver then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function SealEngraver.getStats() return {waxStock=SealEngraver.waxStock,metalStock=SealEngraver.metalStock,goldStock=SealEngraver.goldStock,jewelStock=SealEngraver.jewelStock,productStock=SealEngraver.productStock,numBuildings=#SealEngraver.buildings,hasEngraver=SealEngraver.engraver~=nil,engraverName=SealEngraver.engraver and SealEngraver.engraver.name or "—",engraverSkill=SealEngraver.engraver and SealEngraver.engraver.skill or 0,activeMaking=#SealEngraver.activeMaking,totalProducts=SealEngraver.totalProducts} end
return SealEngraver
